from nltk.tokenize import word_tokenize 
from nltk.corpus import stopwords
from collections import Counter
import numpy as np
import pandas as pd

# a function to tokenize each message. 
def separate_words(string):
	# split them strings into their constituent words
    words = word_tokenize(string.lower());

    # loop through words and discard those belonging to the stopword list
	no_stopwords = [];
	for word in words:
		if word not in stopwords.words('english'):
			no_stopwords.append(word);

	return no_stopwords;

# a function to take each message and count its tokens
def token_counter(words):
	counts = Counter(words);
	return counts;

# load the data set
df = pd.read_csv('data.csv');

# create a temporary list with the counts of each message
data = [];
for i in range(df.shape[0]):
	words = separate_words(df['message'][i]);
	tokens = token_counter(words);
	data.append(tokens);

# prepare the input features and labels	
X = pd.DataFrame(data).fillna(0).astype(int).values;
y = df['label'].replace({'spam':1, 'not spam':0}).values;

# build the Naive Bayes model
from sklearn.naive_bayes import MultinomialNB

model = MultinomialNB();
model.fit(X, y);

# test the model
test_string = 'This message is potentially spam.';

# tokenize and make a counter
words = separate_words(test_string.lower());
tokens = token_counter(words);

# turn the token counter into a array
test_data = [tokens];
test_data = pd.DataFrame(test_data).fillna(0).astype(int).values;

# make the prediction
prediction = model.predict(test_data);

# print the prediction
if prediction == 1:
	print('This message is a spam.');
else:
	print('This message is a not a spam.');
