import tensorflow as tf
import numpy as np

# Define the environment
env_row = 6
env_col = 6
obstacle = np.array([[3, 3], [3, 4], [3, 5], [4, 3], [5, 3]])

# The agent can move in 4 directions
action_space = 4

# Define the reward and penalty
reward_pos = 0
penalty_pos = -1
reward_goal = 100
penalty_collision = -20

# Get the available actions
# 0 - up, 1 - right, 2 - down, 3 - left
def get_actions(x, y):
 if x == 0 and y == 0:
 return np.array([2, 1])
 elif x == 0 and y == (env_col-1):
 return np.array([2, 3])
 elif x == (env_row-1) and y == 0:
 return np.array([0, 1])
 elif x == (env_row-1) and y == (env_col-1):
 return np.array([0, 3])
 elif x == 0:
 return np.array([2, 1, 3])
 elif y == 0:
 return np.array([0, 1, 2])
 elif x == (env_row-1):
 return np.array([0, 1, 3])
 elif y == (env_col-1):
 return np.array([0, 2, 3])
 else:
 return np.array([0, 1, 2, 3])

# Get the next state
def get_next_state(x, y, action):
 if action == 0:
 next_state_x = x-1
 next_state_y = y
 elif action == 1:
 next_state_x = x
 next_state_y = y+1
 elif action == 2:
 next_state_x = x+1
 next_state_y = y
 elif action == 3:
 next_state_x = x
 next_state_y = y-1

 return [next_state_x, next_state_y]

# Define the parameters for the RL model
learning_rate = 0.5
discount_factor = 0.9

# Build the model
model = tf.keras.models.Sequential()
model.add(tf.keras.layers.Dense(env_row * env_col, activation='relu', kernel_initializer='he_uniform'))
model.add(tf.keras.layers.Dense(env_row * env_col * action_space, activation='linear'))
model.compile(optimizer=tf.keras.optimizers.Adam(lr=learning_rate), loss='mse')

# Function to train the model
def train(state, action, next_state, reward) :
 target = reward + discount_factor * np.amax(model.predict(next_state))
 q_value = model.predict(state)
 q_value[0][action] = target
 model.fit(state, q_value, verbose=0)

# Function to select the action based on epsilon-greedy
def select_action(current_state):
 action_space = get_actions(*current_state)
 action = np.random.randint(len(action_space))
 if np.random.random() < 0.5:
 q_value = model.predict(current_state)
 action = np.argmax(q_value[0])
 return action_space[action]

# Function to reset the game
def reset():
 init_state = [0, 0]
 goal_state = [5, 5]
 current_state = np.array(init_state)
 return current_state, init_state, goal_state

# Function to play the game
def play(episode):
 total_step = 0
 for ep in range(episode):
 # Reset the game
 current_state, init_state, goal_state = reset()

 # Select the action
 action = select_action(current_state)

 # Get the next state
 next_state = get_next_state(*current_state, action)

 # Set the reward
 reward = 0
 if np.array_equal(next_state, goal_state):
 reward = reward_goal
 if np.array_equal(current_state, obstacle).any():
 reward = penalty_collision
 else:
 reward = penalty_pos

# Train the model
 train(current_state, action, next_state, reward)

# Get the next action
 current_state = next_state
 action = select_action(current_state)

# Increment the total step
 total_step += 1

# If the goal is reached or max step is reached, reset the game
 if np.array_equal(current_state, goal_state):
 print("Goal reached!")
 break

if total_step >= 50:
 print("Max step reached!")
 break

print("Total step:", total_step)
