import random
import matplotlib.pyplot as plt

def f(x, y):
 return 3*x**2 + 4*x*y + y**2

def generate_random_solution():
 x = random.uniform(-10, 10)
 y = random.uniform(-10, 10)
 return (x, y)

def evaluate_fitness(solution):
 x, y = solution
 return f(x, y)

def generate_new_solutions(solution):
 x, y = solution
 x_new = x + random.uniform(-1, 1)
 y_new = y + random.uniform(-1, 1)
 return (x_new, y_new)

def main():
 max_iter = 1000
 population_size = 100
 population = [generate_random_solution() for _ in range(population_size)]
 fitness = [evaluate_fitness(solution) for solution in population]
 best_sol = population[fitness.index(max(fitness))]

for _ in range(max_iter): 
 new_solutions = [generate_new_solutions(solution) for solution in population]
 new_fitness = [evaluate_fitness(solution) for solution in new_solutions]

for i in range(population_size):
 if new_fitness[i] > fitness[i]:
 population[i] = new_solutions[i]
 fitness[i] = new_fitness[i]

if max(new_fitness) > max(fitness):
 best_sol = new_solutions[fitness.index(max(fitness))]

print(f"Maxima of f(x,y): {max(fitness)}")
print(f"x: {best_sol[0]}, y: {best_sol[1]}")

if __name__ == "__main__":
 main()
```

